using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Adds a local message to a chat. The message is persistent across application restarts only if the message database is used. Returns the added message
    /// </summary>
    public Task<TdLib.TdApi.Objects.Message> AddLocalMessageAsync(long chatId = default, MessageSender senderId = default, InputMessageReplyTo replyTo = default, bool disableNotification = default, InputMessageContent inputMessageContent = default)
    {

           using var activity =  StartCallActivity("AddLocalMessageAsync", typeof(AddLocalMessage).FullName ?? "AddLocalMessageAsync");

           try
           {
             return client.AddLocalMessageAsync(chatId, senderId, replyTo, disableNotification, inputMessageContent);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
